package functions
import "../state"
write :: proc(p: ^state.Store) {p.value = 1}
forward :: proc(p: ^state.Store) {alias := write; alias(p)}
invoke :: proc(p: ^state.Store, callback: proc(^state.Store)) {callback(p)}
patch :: proc(first, second: ^state.Store) {first^ = second^; second.value = 3}
